using System;
using System.Collections.Generic;
using System.IO;
using UnityEngine;

namespace SurvivorLab {
    // Generated by ArtSource/generate_art.py; visual only, the simulation has no obstacles.
    [Serializable] public class BackgroundDecoration { public string type; public float x, y; }
    [Serializable] public class BackgroundMap {
        public int version, width, height, tileSize; public float originX, originY, arenaHalfExtent;
        public string image; public string[] legend, rows; public BackgroundDecoration[] decorations;
    }
    public sealed class GameApp : MonoBehaviour {
        Balance balance; Simulation sim; Learning agent; Trainer trainer;
        bool menu=true, ai, paused, autoRewards; int selected, speed=1, action; float accumulator, actionAt;
#if UNITY_EDITOR || DEVELOPMENT_BUILD
        bool smoke;
        float smokeStart, smokeCaptureAt=4, smokeQuitAt=6; int smokePhase;
        bool recordDemo; int demoFrame; float demoFrameAt; string demoDirectory;
#endif
        float rewardChoiceAt=-1;
#if UNITY_EDITOR || DEVELOPMENT_BUILD
        bool verifyAutoRewards;
#endif
        Camera cam; Material material; readonly Dictionary<string,GameObject> views=new Dictionary<string,GameObject>();
        readonly HashSet<string> used=new HashSet<string>(); Font font; string status="";
        readonly Dictionary<string,Texture2D> art=new Dictionary<string,Texture2D>();
        static readonly string[] MonsterKinds={"slime","bat","ghost"};
        RewardLearner learnedRewards; bool useLearnedRewards, faceLeft; BackgroundMap map;
        IRewardChooser Chooser { get { return useLearnedRewards && learnedRewards!=null ? (IRewardChooser)learnedRewards : RuleRewardChooser.Instance; } }
        string PolicyPath { get { return Path.Combine(Application.persistentDataPath,"policy-v2.json"); } }
        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]
        static void Boot() { if(FindFirstObjectByType<GameApp>()==null) new GameObject("Survivor Lab").AddComponent<GameApp>(); }
        void Start() {
            Application.targetFrameRate=60; balance=Balance.Load(); agent=new Learning();
            if(File.Exists(PolicyPath)) agent.Load(PolicyPath);
            else agent.Load(Path.Combine(Application.streamingAssetsPath,"initial-policy-v2.json"));
            Debug.Log("Policy loaded: episodes="+agent.data.episodes+", states="+agent.data.rows.Count);
            string rewardPolicy=Path.Combine(Application.streamingAssetsPath,"reward-policy.json");
            try {
                if(File.Exists(rewardPolicy)) { learnedRewards=new RewardLearner(JsonUtility.FromJson<RewardPolicyFile>(File.ReadAllText(rewardPolicy)),1); useLearnedRewards=true; }
                Debug.Log(learnedRewards==null?"Reward policy missing: rule-based reward choice":"Reward policy loaded: method="+learnedRewards.data.method+", episodes="+learnedRewards.data.episodes);
            } catch(Exception e) { learnedRewards=null; Debug.LogWarning("Reward policy rejected, using rules: "+e.Message); }
            LoadArt();
            cam=Camera.main;
            if(cam==null) cam=new GameObject("Camera").AddComponent<Camera>();
            cam.orthographic=true; cam.orthographicSize=13; cam.transform.rotation=Quaternion.Euler(90,0,0);
            cam.backgroundColor=new Color(0.025f,0.045f,0.075f); cam.clearFlags=CameraClearFlags.SolidColor;
            material=Resources.Load<Material>("GameMaterial");
            if(material==null) material=new Material(Shader.Find("Sprites/Default"));
            font=Font.CreateDynamicFontFromOSFont(new[]{"Malgun Gothic","Arial"},18);
#if UNITY_EDITOR || DEVELOPMENT_BUILD
            var args=Environment.GetCommandLineArgs();
            foreach(var arg in args) if(arg.StartsWith("--smoke")) Application.runInBackground=true;
            foreach(var arg in args) if(arg.StartsWith("--class=")) selected=Mathf.Clamp(int.Parse(arg.Substring(8)),0,3);
            if(Array.IndexOf(args,"--qa")>=0) { try { QualityChecks.Run(balance); Application.Quit(0); } catch(Exception e) { Debug.LogException(e); Application.Quit(1); } }
            if(Array.IndexOf(args,"--smoke")>=0) { smoke=true; smokeStart=Time.realtimeSinceStartup; Begin(true); }
            if(Array.IndexOf(args,"--smoke-menu")>=0) { smoke=true; smokeStart=Time.realtimeSinceStartup; }
            if(Array.IndexOf(args,"--record-demo")>=0) {
                Application.runInBackground=true;
                smoke=true; recordDemo=true; smokeStart=Time.realtimeSinceStartup;
                smokeQuitAt=24; smokeCaptureAt=22;
                demoDirectory=Path.Combine(Application.persistentDataPath,"demo-frames");
                Directory.CreateDirectory(demoDirectory);
                speed=2; Begin(true);
            }
            if(Array.IndexOf(args,"--smoke-growth")>=0) {
                smoke=true; smokeStart=Time.realtimeSinceStartup; smokeCaptureAt=14; smokeQuitAt=16;
                speed=4; autoRewards=true; Begin(true);
            }
            if(Array.IndexOf(args,"--smoke-ai-rewards")>=0) {
                smoke=true; verifyAutoRewards=true; smokeStart=Time.realtimeSinceStartup;
                smokeCaptureAt=12; smokeQuitAt=14; Begin(true);
                float required=0; for(int l=1;l<14;l++) required+=balance.RequiredXp(l);
                sim.GainXp(required+0.01f);
            }
            foreach(string flag in new[]{"--smoke-level","--smoke-infusion1","--smoke-infusion2"}) if(Array.IndexOf(args,flag)>=0) {
                smoke=true; smokeStart=Time.realtimeSinceStartup; Begin(false);
                int target=flag=="--smoke-infusion2"?14:7; float required=0;
                for(int l=1;l<target;l++) required+=balance.RequiredXp(l);
                sim.GainXp(required+0.01f);
                while(sim.offers.Count>0) {
                    bool stop=flag=="--smoke-level"?sim.rewardLevel==target:sim.offers[0].infusion && sim.rewardLevel==target;
                    if(stop) break;
                    sim.Choose(0);
                }
            }
#endif
        }
        void SetControl(bool watch) { ai=watch; autoRewards=watch; rewardChoiceAt=-1; }
        void Begin(bool watch) { SetControl(watch); sim=new Simulation(balance,selected,90210){rewardChooser=Chooser}; menu=false; paused=false; accumulator=actionAt=0; }
        void LoadArt() {
            string root=Path.Combine(Application.streamingAssetsPath,"Art");
            var files=new List<string>{"background/arena","items/xp","items/potion","items/rock","items/bolt","items/shadow"};
            foreach(var s in balance.spells) for(int f=0;f<2;f++) files.Add("characters/"+s.id+"_"+f);
            foreach(var m in MonsterKinds) for(int f=0;f<2;f++) files.Add("monsters/"+m+"_"+f);
            foreach(var name in files) {
                string file=Path.Combine(root,name+".png");
                if(!File.Exists(file)) { Debug.LogWarning("Art missing, using primitive: "+name); continue; }
                var tex=new Texture2D(2,2,TextureFormat.RGBA32,false);
                if(!tex.LoadImage(File.ReadAllBytes(file))) { Debug.LogWarning("Art unreadable: "+name); continue; }
                tex.filterMode=FilterMode.Point; tex.wrapMode=TextureWrapMode.Clamp; art[name]=tex;
            }
            Debug.Log("Art loaded: "+art.Count+" / "+files.Count);
            string mapFile=Path.Combine(root,"background/background-map.json");
            if(art.ContainsKey("background/arena") && File.Exists(mapFile)) {
                map=JsonUtility.FromJson<BackgroundMap>(File.ReadAllText(mapFile));
                if(map.rows==null || map.rows.Length!=map.height || map.arenaHalfExtent!=balance.arenaHalfExtent) { Debug.LogWarning("Background map does not match arena; using plain floor"); map=null; }
                else Debug.Log("Background map: "+map.width+"x"+map.height+" tiles, decorations="+map.decorations.Length);
            }
        }
        void Update() {
            if(balance==null) return;
#if UNITY_EDITOR || DEVELOPMENT_BUILD
            if(recordDemo && Time.realtimeSinceStartup>=demoFrameAt && Time.realtimeSinceStartup-smokeStart<smokeQuitAt) {
                ScreenCapture.CaptureScreenshot(Path.Combine(demoDirectory,(demoFrame++).ToString("D5")+".png"));
                demoFrameAt=Time.realtimeSinceStartup+0.125f;
            }
            if(smoke && Time.realtimeSinceStartup-smokeStart>smokeCaptureAt && smokePhase==0) {
                if(verifyAutoRewards && (sim.infusions.Count!=2 || sim.automaticChoices!=15 || sim.offers.Count!=0)) {
                    Debug.LogError("AI reward integration check failed"); Application.Quit(1); return;
                }
                if(verifyAutoRewards) Debug.Log("AI REWARD INTEGRATION PASS: 15 automatic decisions, two infusions, no pending offer");
                if(sim!=null) Debug.Log($"SMOKE PROGRESSION time={sim.time:F2} level={sim.level} collectedOrbs={sim.collectedOrbs} totalXp={sim.totalXp:F2} infusions={sim.infusions.Count}");
                ScreenCapture.CaptureScreenshot(Path.Combine(Application.persistentDataPath,"smoke.png")); smokePhase=1;
            }
            if(smoke && Time.realtimeSinceStartup-smokeStart>smokeQuitAt) Application.Quit(0);
#endif
            if(Input.GetKeyDown(KeyCode.Escape)) { menu=true; trainer?.Stop(); }
            if(Input.GetKeyDown(KeyCode.Space)) paused=!paused;
            if(trainer!=null && trainer.active) {
                trainer.Pump(300);
                if(!trainer.active) { agent.Save(PolicyPath); status="Training saved. Watch AI to inspect the policy."; }
                return;
            }
            if(menu || sim==null || paused || sim.Done) return;
            if(sim.offers.Count>0) {
                if(ai && autoRewards) {
                    if(rewardChoiceAt<0) rewardChoiceAt=Time.realtimeSinceStartup+0.65f;
                    if(Time.realtimeSinceStartup>=rewardChoiceAt) {
                        sim.ChooseAutomatically(); rewardChoiceAt=-1;
                        Debug.Log("AI REWARD: "+sim.lastAutoChoice);
                    }
                }
                else for(int i=0;i<sim.offers.Count;i++) if(Input.GetKeyDown(KeyCode.Alpha1+i)) { sim.Choose(i); break; }
                return;
            }
            rewardChoiceAt=-1;
            accumulator+=Mathf.Min(Time.unscaledDeltaTime,0.1f)*speed;
            while(accumulator>=0.05f) {
                accumulator-=0.05f;
                Vector2 input;
                if(ai) {
                    if(sim.time>=actionAt) { action=agent.Act(Learning.Observe(sim),0); actionAt=sim.time+0.1f; }
                    input=Learning.Actions[action];
                } else input=new Vector2((Input.GetKey(KeyCode.D)||Input.GetKey(KeyCode.RightArrow)?1:0)-(Input.GetKey(KeyCode.A)||Input.GetKey(KeyCode.LeftArrow)?1:0),(Input.GetKey(KeyCode.W)||Input.GetKey(KeyCode.UpArrow)?1:0)-(Input.GetKey(KeyCode.S)||Input.GetKey(KeyCode.DownArrow)?1:0));
                sim.Step(input,0.05f,false);
                if(sim.Done || sim.offers.Count>0) { accumulator=0; break; }
            }
        }
        void Item(string key, PrimitiveType type, Vector2 p, Vector3 size, Color color, Vector2 direction=default(Vector2)) {
            used.Add(key); GameObject obj;
            if(!views.TryGetValue(key,out obj)) {
                obj=GameObject.CreatePrimitive(type); Destroy(obj.GetComponent<Collider>());
                obj.GetComponent<Renderer>().sharedMaterial=material; views[key]=obj;
            }
            obj.SetActive(true); obj.transform.position=new Vector3(p.x,size.y/2,p.y); obj.transform.localScale=size;
            obj.transform.rotation=direction.sqrMagnitude>0?Quaternion.LookRotation(new Vector3(direction.x,0,direction.y)):Quaternion.identity;
            var block=new MaterialPropertyBlock(); block.SetColor("_Color",color); obj.GetComponent<Renderer>().SetPropertyBlock(block);
        }
        // Flat textured quad facing the top-down camera. Returns false when the art file is missing.
        bool Sprite(string key, string name, Vector2 p, float width, float height, Color color, float layer, bool flip=false) {
            Texture2D tex; if(!art.TryGetValue(name,out tex)) return false;
            used.Add(key); GameObject obj;
            if(!views.TryGetValue(key,out obj)) {
                obj=GameObject.CreatePrimitive(PrimitiveType.Quad); Destroy(obj.GetComponent<Collider>());
                obj.GetComponent<Renderer>().sharedMaterial=material; views[key]=obj;
            }
            obj.SetActive(true); obj.transform.position=new Vector3(p.x,layer,p.y);
            obj.transform.rotation=Quaternion.Euler(90,0,0); obj.transform.localScale=new Vector3(flip?-width:width,height,1);
            var block=new MaterialPropertyBlock(); block.SetTexture("_MainTex",tex); block.SetColor("_Color",color); obj.GetComponent<Renderer>().SetPropertyBlock(block);
            return true;
        }
        void LateUpdate() {
            if(sim==null || menu) { foreach(var o in views.Values) o.SetActive(false); return; }
            used.Clear(); cam.transform.position=new Vector3(sim.player.x,30,sim.player.y);
            if(map!=null) Sprite("background","background/arena",new Vector2(map.originX+map.width/2f,map.originY+map.height/2f),map.width,map.height,Color.white,-0.1f);
            else {
                Item("floor",PrimitiveType.Cube,Vector2.zero,new Vector3(balance.arenaHalfExtent*2+2,0.05f,balance.arenaHalfExtent*2+2),new Color(0.08f,0.12f,0.17f));
                views["floor"].transform.position=new Vector3(0,-0.1f,0);
            }
            if(sim.facing.x<-0.01f) faceLeft=true; else if(sim.facing.x>0.01f) faceLeft=false;
            int step=sim.stillTime==0 && sim.time>0?((int)(sim.time*7))%2:0;
            Sprite("player-shadow","items/shadow",sim.player+new Vector2(0,-0.5f),1.1f,0.5f,Color.white,0.02f);
            if(!Sprite("player","characters/"+sim.Spell.id+"_"+step,sim.player+new Vector2(0,0.3f),1.7f,1.7f,Color.white,0.3f,faceLeft))
                Item("player",PrimitiveType.Capsule,sim.player,new Vector3(0.7f,0.6f,0.7f),new Color(0.2f,0.9f,0.8f),sim.facing);
            Item("facing",PrimitiveType.Cube,sim.player+sim.facing*1.05f,new Vector3(0.12f,0.05f,0.4f),new Color(1,1,1,0.7f),sim.facing);
            if(sim.shield>0) Item("shield",PrimitiveType.Cylinder,sim.player,new Vector3(1.2f,0.06f,1.2f),new Color(0.3f,0.7f,1,0.35f));
            if(sim.time<sim.pulseUntil) {
                float r=sim.Spell.radius*(1+sim.radiusBonus/100);
                var tint=SpellColor(); tint.a=0.3f;
                Item("pulse",PrimitiveType.Cylinder,sim.player,new Vector3(r*2,0.02f,r*2),tint);
            }
            foreach(var e in sim.enemies) {
                // Sprites keep their own colours, so status tints are lighter than the primitive fallback.
                bool sprite=art.ContainsKey("monsters/slime_0");
                Color tint=sprite?Color.white:new Color(0.95f,0.28f,0.38f);
                if(sim.time<e.chillUntil || sim.time<e.slowUntil) tint=sprite?new Color(0.55f,1,1):Color.cyan;
                if(e.burnRemaining>0) tint=sprite?new Color(1,0.62f,0.35f):new Color(1,0.5f,0.1f);
                if(sim.time<e.acidUntil) tint=sprite?new Color(0.6f,1,0.45f):Color.green;
                if(e.corruptionDamage>0) tint=sprite?new Color(0.82f,0.5f,1):new Color(0.7f,0.2f,1);
                if(sim.time<e.frozenUntil) tint=sprite?new Color(0.7f,0.9f,1,0.85f):Color.white;
                // Monster look is cosmetic (by id); every enemy uses the same simulation stats.
                string look="monsters/"+MonsterKinds[e.id%MonsterKinds.Length]+"_"+(((int)(sim.time*4)+e.id)%2);
                Sprite("enemy-shadow"+e.id,"items/shadow",e.pos+new Vector2(0,-0.4f),0.9f,0.4f,Color.white,0.02f);
                if(!Sprite("enemy"+e.id,look,e.pos+new Vector2(0,0.15f),1.25f,1.25f,tint,0.1f-e.pos.y*0.0005f,e.pos.x>sim.player.x))
                    Item("enemy"+e.id,PrimitiveType.Capsule,e.pos,new Vector3(0.65f,0.5f,0.65f),tint);
            }
            for(int i=0;i<sim.drops.Count;i++) {
                var d=sim.drops[i];
                if(!Sprite("drop"+i,d.potion?"items/potion":"items/xp",d.pos+new Vector2(0,Mathf.Sin(sim.time*4+i)*0.08f),d.potion?0.95f:0.8f,d.potion?0.95f:0.8f,Color.white,0.05f))
                    Item("drop"+i,PrimitiveType.Sphere,d.pos,Vector3.one*(d.potion?0.5f:0.42f),d.potion?Color.green:new Color(0.4f,0.65f,1));
            }
            for(int i=0;i<sim.rocks.Count;i++) if(!Sprite("rock"+i,"items/rock",sim.rocks[i].pos,1,1,Color.white,0.04f))
                Item("rock"+i,PrimitiveType.Sphere,sim.rocks[i].pos,new Vector3(0.65f,0.25f,0.65f),new Color(0.65f,0.5f,0.3f));
            for(int i=0;i<sim.bolts.Count;i++) if(!Sprite("bolt"+i,"items/bolt",sim.bolts[i].pos,1.1f,1.1f,SpellColor(),0.4f))
                Item("bolt"+i,PrimitiveType.Sphere,sim.bolts[i].pos,Vector3.one*0.35f,SpellColor());
            var nearest=sim.NearestXp();
            if(nearest!=null) {
                Vector2 d=(nearest.pos-sim.player).normalized;
                Item("xp-guide",PrimitiveType.Cube,sim.player+d*1.5f,new Vector3(0.22f,0.12f,0.8f),new Color(0.4f,0.65f,1),d);
            }
            for(int i=0;i<sim.elementVisuals.Count;i++) {
                var v=sim.elementVisuals[i];
                if(v.beam) Item("element"+i,PrimitiveType.Cube,(v.from+v.to)/2,new Vector3(0.12f,0.25f,Vector2.Distance(v.from,v.to)),Color.yellow,(v.to-v.from).normalized);
                else Item("element"+i,PrimitiveType.Cylinder,v.from,new Vector3(v.radius*2,0.06f,v.radius*2),new Color(0.7f,0.2f,1,0.45f));
            }
            for(int i=0;i<sim.slams.Count;i++) {
                var s=sim.slams[i]; var side=new Vector2(s.dir.y,-s.dir.x); float spread=s.resolved?0:Mathf.Clamp01((s.resolveAt-sim.time)/sim.Spell.telegraph)*sim.Spell.width/2;
                Item("slamL"+i,PrimitiveType.Cube,s.pos+s.dir*sim.Spell.length/2+side*spread,new Vector3(0.18f,0.45f,sim.Spell.length),s.resolved?Color.white:new Color(0.9f,0.5f,1,0.8f),s.dir);
                Item("slamR"+i,PrimitiveType.Cube,s.pos+s.dir*sim.Spell.length/2-side*spread,new Vector3(0.18f,0.45f,sim.Spell.length),s.resolved?Color.white:new Color(0.9f,0.5f,1,0.8f),s.dir);
            }
            foreach(var v in views) if(!used.Contains(v.Key)) v.Value.SetActive(false);
        }
        Color SpellColor() {
            var effect=sim.ActiveElement;
            if(effect==null) return new Color(1,0.75f,0.1f);
            if(effect.id.Contains("Dark")) return new Color(0.7f,0.3f,1);
            if(effect.id.Contains("Fire")) return new Color(1,0.45f,0.1f);
            if(effect.id.Contains("Acid")) return Color.green;
            if(effect.id.Contains("Ice")) return Color.cyan;
            return Color.yellow;
        }
        string OwnedScrollNames() {
            var names=new List<string>();
            foreach(string id in sim.owned) names.Add(balance.Scroll(id)?.name ?? id);
            return string.Join(", ",names);
        }
        void OnGUI() {
            if(balance==null) return;
            GUI.skin.font=font; GUI.skin.label.fontSize=17; GUI.skin.button.fontSize=17; GUI.skin.box.fontSize=17;
            GUI.skin.button.wordWrap=true;
            GUI.matrix=Matrix4x4.Scale(new Vector3(Screen.width/1280f,Screen.height/800f,1));
            GUI.Box(new Rect(15,15,1250,95),"SURVIVOR LAB / UNITY     |     WASD / arrows: move     Space: pause     Esc: menu");
            if(menu) {
                GUI.Label(new Rect(65,145,1150,50),"One character, one spell. Survive 5 minutes. Select a class:");
                for(int i=0;i<4;i++) { GUI.backgroundColor=selected==i?new Color(0.2f,0.9f,0.8f):Color.white; if(GUI.Button(new Rect(65+i*295,210,280,90),balance.spells[i].name)) selected=i; }
                GUI.backgroundColor=Color.white;
                if(GUI.Button(new Rect(65,335,350,65),"PLAY / 직접 플레이")) Begin(false);
                if(GUI.Button(new Rect(445,335,350,65),"WATCH AI / AI 관전")) Begin(true);
                if(GUI.Button(new Rect(825,335,350,65),"TRAIN +400 episodes")) { trainer=new Trainer(balance,agent,400,Chooser); status=""; }
                GUI.Label(new Rect(65,430,1150,110),"이동: 표 기반 Q-learning v2 | 학습 횟수: "+agent.data.episodes+" | 두루마리 19종\n파란 경험치를 모아 레벨업 → 3개 중 선택 → 7·14레벨에 속성 부여\nAI 보상 선택: "+Chooser.Name+(learnedRewards!=null?" (학습 "+learnedRewards.data.episodes+"회)":" (학습 정책 파일 없음)"));
                GUI.enabled=learnedRewards!=null;
                if(GUI.Button(new Rect(825,545,350,50),"보상 판단: "+(Chooser==RuleRewardChooser.Instance?"규칙 기반":"학습 정책"))) useLearnedRewards=!useLearnedRewards;
                GUI.enabled=true;
                if(trainer!=null && trainer.active) {
                    GUI.Label(new Rect(65,530,1150,60),"Training "+trainer.completed+" / "+trainer.target+"   Last survival: "+trainer.lastSurvival.ToString("F1")+"s");
                    if(GUI.Button(new Rect(65,610,350,60),"STOP & SAVE")) { trainer.Stop(); agent.Save(PolicyPath); }
                }
                GUI.Label(new Rect(65,700,1150,70),status);
                return;
            }
            GUI.Label(new Rect(35,55,1190,45),$"{(ai?"AI":"MANUAL")} | {sim.Spell.name} | HP {sim.hp:F1}/{sim.maxHp:F0}  Shield {sim.shield:F1} | LV {sim.level}  XP {sim.xp:F1}/{balance.RequiredXp(sim.level):F1} | {sim.time:F1}s | Kills {sim.kills}");
            GUI.Box(new Rect(20,112,1240,24),"");
            var oldColor=GUI.color; GUI.color=new Color(0.3f,0.6f,1);
            GUI.DrawTexture(new Rect(22,114,1236*Mathf.Clamp01(sim.xp/balance.RequiredXp(sim.level)),20),Texture2D.whiteTexture); GUI.color=oldColor;
            GUI.Label(new Rect(30,145,1010,50),"파란 구슬을 향해 이동하세요 · 가까워지면 자동 흡수\n속성: "+(sim.ActiveElement==null?"없음":sim.ActiveElement.name)+"  ["+sim.infusions.Count+"/2] · "+(sim.infusions.Count<2?"다음 부여 LV "+balance.infusionLevels[sim.infusions.Count]:"부여 완료"));
            if(sim.offers.Count==0 && sim.time-sim.lastPickupAt<1.2f) GUI.Label(new Rect(580,440,250,40),sim.lastPickupText);
            bool controlsEnabled=GUI.enabled; GUI.enabled=controlsEnabled && sim.offers.Count==0;
            if(GUI.Button(new Rect(1090,145,175,40),"Speed: "+speed+"x")) speed=speed==1?2:speed==2?4:1;
            if(GUI.Button(new Rect(1090,190,175,40),ai?"직접 조작":"AI 관전")) SetControl(!ai);
            if(GUI.Button(new Rect(1090,235,175,40),"보상 자동: "+(autoRewards?"켬":"끔"))) autoRewards=!autoRewards;
            GUI.enabled=controlsEnabled && sim.offers.Count==0 && learnedRewards!=null;
            if(GUI.Button(new Rect(1090,280,175,40),"판단: "+(Chooser==RuleRewardChooser.Instance?"규칙":"학습"))) { useLearnedRewards=!useLearnedRewards; sim.rewardChooser=Chooser; }
            GUI.enabled=controlsEnabled;
            GUI.Label(new Rect(20,710,1050,85),"두루마리: "+OwnedScrollNames()+$"\nDamage {sim.Damage:F2} | Attack interval {sim.Interval:F3}s | Move {sim.MoveSpeed:F2} | Armor {sim.Armor:F0}");
            if(ai && sim.lastAutoChoice!="") GUI.Label(new Rect(20,670,1100,35),"AI 선택: "+sim.lastAutoChoice);
            if(sim.offers.Count>0) {
                GUI.color=new Color(0.015f,0.025f,0.04f,0.98f);
                GUI.DrawTexture(new Rect(0,0,1280,800),Texture2D.whiteTexture); GUI.color=oldColor;
                GUI.Box(new Rect(70,240,1140,390),sim.rewardTitle+(ai&&autoRewards?" · AI가 자동 선택 중 ("+sim.rewardChooser.Name+")":" · 3개 중 1개 선택 (1 / 2 / 3)")+" · 게임 시간 정지");
                for(int i=0;i<sim.offers.Count;i++) if(GUI.Button(new Rect(95+i*365,300,345,280),(i+1)+". "+sim.offers[i].label)) { sim.Choose(i); break; }
            }
            if(paused) GUI.Box(new Rect(440,330,400,100),"PAUSED / Space to resume");
            if(sim.Done) {
                GUI.Box(new Rect(350,270,580,190),sim.won?"SURVIVED / 생존 성공":"GAME OVER");
                if(GUI.Button(new Rect(400,350,210,60),"Retry")) Begin(ai);
                if(GUI.Button(new Rect(650,350,210,60),"Menu")) menu=true;
            }
        }
        void OnApplicationFocus(bool focus) {
#if UNITY_EDITOR || DEVELOPMENT_BUILD
            if(smoke) return;
#endif
            if(!focus && !menu) paused=true;
        }
        void OnApplicationQuit() { trainer?.Stop(); if(agent!=null) agent.Save(PolicyPath); }
    }
}
